  '9:51009': {
    explanation: `॥ समाप्तेयं पञ्ञम्युमासंहिता`,
  },
  '10:1001': {
    explanation: `काशी जानेकी इच्छा की`,
  },
  '10:1010': {
    explanation: `प्रसन्‍नतापूर्वक उन्हें प्रणाम किया`,
  },
  '10:1011': {
    explanation: `महात्मा सूतजीका पूजन किया`,
  },
  '10:1012': {
    explanation: `प्रसन्‍नताके साथ उसे सुनिये`,
  },
  '10:1013': {
    explanation: `जञति श्रीजिवमहाएराणे पष्उ्यां कैलायसंहितायां व्यासशौनकादिसंवादो नाय प्रथमो5 ध्याय:`,
  },
  '10:1014': {
    explanation: `नामक पहला अध्याय पूर्ण हुआ`,
  },
  '10:1015': {
    explanation: `यथार्थ तत्त्वका निश्चय है`,
  },
  '10:1016': {
    explanation: `अद्भुत इतिहास कह रहा हूँ`,
  },
  '10:1017': {
    explanation: `शिवके निमित्त तप करने लगीं`,
  },
  '10:1018': {
    explanation: `शिवजीसे कहने लगीं--`,
  },
  '10:1019': {
    explanation: `की, तब वे प्रसन्‍नमनसे देवीसे कहने लगे--`,
  },
  '10:1002': {
    explanation: `विशुद्ध तत्त्वमें स्थित करूँगा`,
  },
  '10:1020': {
    explanation: `साथ देवोद्यानमें चले गये`,
  },
  '10:1021': {
    explanation: `मुखको देखकर यह कहा--`,
  },
  '10:1022': {
    explanation: `प्रणबके निश्चित अर्थकों सुनना चाहती हूँ`,
  },
  '10:1023': {
    explanation: `सम्प्रशस्थ महेशानीं वक्तुं समुपचक्रमे ॥ ३० लगे--`,
  },
  '10:1024': {
    explanation: `ड्र्ति “2226० हा केलाससंहितायां देवीदेवसंवादे देवीकृतप्रश्नवर्णन॑ नाम द्वितीयोउ ध्याय:`,
  },
  '10:1025': {
    explanation: `प्रश्नवर्णन नामक दूसरा अध्याय पूर्ण हुआ`,
  },
  '10:1026': {
    explanation: `सुननेमात्रसे जीव साक्षात् शिव हो जाता है`,
  },
  '10:1027': {
    explanation: `नामक वह मन्त्र सभी विद्याओंका बीज है`,
  },
  '10:1028': {
    explanation: `एकाक्षर मन्त्रमें निवास करता हूँ`,
  },
  '10:1029': {
    explanation: `संसारका निर्माण करते हैं`,
  },
  '10:1003': {
    explanation: `एकाक्षर कहते हैं`,
  },
  '10:1030': {
    explanation: `परमेश्वरके रूपमें समझे`,
  },
  '10:1031': {
    explanation: `मन्हत्रोंमें श्रेष्ठ इसी प्रणणका उपदेश करता हूँ`,
  },
  '10:1032': {
    explanation: `प्राप्त हो जाती है`,
  },
  '10:1033': {
    explanation: `करनेवालोंको सदा मुक्ति प्रदान करता है`,
  },
  '10:1034': {
    explanation: `संयोगसे 'ओम्' बनता है`,
  },
  '10:1035': {
    explanation: `स्थित मकार अग्निकी भाँति तेजोमय है`,
  },
  '10:1036': {
    explanation: `उसे तो ज्ञानीलोग ही जान सकते हैं`,
  },
  '10:1037': {
    explanation: `हैं, इस प्रकारकी भावना सर्वत्र करनी चाहिए`,
  },
  '10:1038': {
    explanation: `पर्यन्त पाँच ब्रह्म स्थित हैं, वे मेरी ही मूर्तियाँ हैं`,
  },
  '10:1039': {
    explanation: `प्रणवका अधिकारी है`,
  },
  '10:1004': {
    explanation: `अपना विचार निवेदन करना चाहिए`,
  },
  '10:1040': {
    explanation: `गर्भमें ही योगयुक्त हो गये थे`,
  },
  '10:1041': {
    explanation: `आलेहहह्ड  थक साथ मेरा स्मरण सदा करता रहे`,
  },
  '10:1042': {
    explanation: `मत्तो विज्ञानमासाद्य मत्सायुज्यफलं प्रिये॥ ७०  फल प्राप्त कर लेता है`,
  },
  '10:1043': {
    explanation: `गति श्रीशिवयहाएुराणे पष्ठ्यां कैलाससंहितायों संन्यासपद्धतिवर्णन॑ 7774: तृतीयो5 ध्याय:`,
  },
  '10:1044': {
    explanation: `नामक तीसरा अध्याय पूर्ण हुआ`,
  },
  '10:1045': {
    explanation: `तब स्नेहान्महादेवि संप्रदायानुरोधत:॥ १  लेनेसे पूर्वके आहिक कर्मका वर्णन करूँगा`,
  },
  '10:1046': {
    explanation: `बाहर निकलकर सुविधानुरूप दूर चला जाय`,
  },
  '10:1005': {
    explanation: `लेपनकर स्नान करे`,
  },
  '10:1006': {
    explanation: `आचमनकर तीन प्रणायाम करे`,
  },
  '10:1007': {
    explanation: `करे और वहाँ क्रमसे मण्डलकी रचना करे`,
  },
  '10:1008': {
    explanation: `इति श्रीशिवमहापुराणे वष्ठ्यां केलाससंहितायां संन्यासाचारवर्णन॑ नाम चतुर्थो3 ध्याय:`,
  },
  '10:1009': {
    explanation: `नामक चौथा अध्याय पूर्ण हुआ`,
  },
  '10:2000': {
    explanation: `कक मनन चतुरस्त्र प्रकल्पयेत्॥ २  प्रमाणके चौकोर मण्डलका निर्माण करे`,
  },
  '10:2001': {
    explanation: `करके 'सू' लिखे`,
  },
  '10:2010': {
    explanation: `इस श्रेष्ठ बीजमन्त्रको पद्मयके मध्यमें लिखे`,
  },
  '10:2011': {
    explanation: `षट्कोणको काले रंगसे लिखे`,
  },
  '10:2012': {
    explanation: `काला जय हिंगभरे`,
  },
  '10:2013': {
    explanation: `इति श्रीशिवमहापुराणे पष्ठ्यां केलाससंहितायां संन्यासमण्डलविधिवर्णनं नाम पश्चमो5 ध्याय:`,
  },
  '10:2014': {
    explanation: `नामक पाँचवाँ अध्याय पूर्ण हुआ`,
  },
  '10:2015': {
    explanation: `उच्चारण करते हुए विश्विवत् प्राणायाम करे`,
  },
  '10:2016': {
    explanation: `उसकी भी अर्चना करे`,
  },
  '10:2017': {
    explanation: `क्रमश: दूसरे आवरणमें पूजन करे`,
  },
  '10:2018': {
    explanation: `है, इसे ग्रहणकर आप प्रसन्‍न होइये`,
  },
  '10:2019': {
    explanation: `पढ़कर नमस्कार करे`,
  },
